-- Keep Listening - copia exportada de la base SQLite (keep_listening1/db.sqlite3)
-- Integrantes: Sophia Benitez, Ali Perez
-- Restaurar: ver README, seccion Base de datos. Las sesiones abiertas no se exportan.
BEGIN TRANSACTION;
CREATE TABLE "account_emailaddress" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "verified" bool NOT NULL, "primary" bool NOT NULL, "user_id" bigint NOT NULL REFERENCES "usuarios_usuario" ("id") DEFERRABLE INITIALLY DEFERRED, "email" varchar(254) NOT NULL);
CREATE TABLE "account_emailconfirmation" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "created" datetime NOT NULL, "sent" datetime NULL, "key" varchar(64) NOT NULL UNIQUE, "email_address_id" integer NOT NULL REFERENCES "account_emailaddress" ("id") DEFERRABLE INITIALLY DEFERRED);
CREATE TABLE "auth_group" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "name" varchar(150) NOT NULL UNIQUE);
CREATE TABLE "auth_group_permissions" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "group_id" integer NOT NULL REFERENCES "auth_group" ("id") DEFERRABLE INITIALLY DEFERRED, "permission_id" integer NOT NULL REFERENCES "auth_permission" ("id") DEFERRABLE INITIALLY DEFERRED);
CREATE TABLE "auth_permission" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "content_type_id" integer NOT NULL REFERENCES "django_content_type" ("id") DEFERRABLE INITIALLY DEFERRED, "codename" varchar(100) NOT NULL, "name" varchar(255) NOT NULL);
CREATE TABLE "django_admin_log" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "object_id" text NULL, "object_repr" varchar(200) NOT NULL, "action_flag" smallint unsigned NOT NULL CHECK ("action_flag" >= 0), "change_message" text NOT NULL, "content_type_id" integer NULL REFERENCES "django_content_type" ("id") DEFERRABLE INITIALLY DEFERRED, "user_id" bigint NOT NULL REFERENCES "usuarios_usuario" ("id") DEFERRABLE INITIALLY DEFERRED, "action_time" datetime NOT NULL);
CREATE TABLE "django_content_type" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "app_label" varchar(100) NOT NULL, "model" varchar(100) NOT NULL);
CREATE TABLE "django_migrations" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "app" varchar(255) NOT NULL, "name" varchar(255) NOT NULL, "applied" datetime NOT NULL);
CREATE TABLE "django_session" ("session_key" varchar(40) NOT NULL PRIMARY KEY, "session_data" text NOT NULL, "expire_date" datetime NOT NULL);
CREATE TABLE "musica_album" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "titulo" varchar(200) NOT NULL, "slug" varchar(220) NOT NULL UNIQUE, "tipo" varchar(10) NOT NULL, "descripcion" text NOT NULL, "fecha_lanzamiento" date NOT NULL, "portada" varchar(100) NULL, "tipo_disco" varchar(10) NOT NULL, "disponible_digital" bool NOT NULL, "disponible_fisico" bool NOT NULL, "precio_digital" decimal NOT NULL, "precio_fisico" decimal NOT NULL, "stock_fisico" integer unsigned NOT NULL CHECK ("stock_fisico" >= 0), "publicado" bool NOT NULL, "creado" datetime NOT NULL, "artista_id" bigint NOT NULL REFERENCES "usuarios_usuario" ("id") DEFERRABLE INITIALLY DEFERRED, "genero_id" bigint NULL REFERENCES "musica_genero" ("id") DEFERRABLE INITIALLY DEFERRED, "estilo_vinilo" smallint unsigned NULL CHECK ("estilo_vinilo" >= 0), "lista_temas" text NOT NULL CHECK ((JSON_VALID("lista_temas") OR "lista_temas" IS NULL)));
CREATE TABLE "musica_cancion" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "titulo" varchar(200) NOT NULL, "slug" varchar(220) NOT NULL UNIQUE, "tipo" varchar(10) NOT NULL, "numero_pista" smallint unsigned NOT NULL CHECK ("numero_pista" >= 0), "portada" varchar(100) NULL, "archivo_audio" varchar(100) NOT NULL, "duracion_segundos" integer unsigned NOT NULL CHECK ("duracion_segundos" >= 0), "estado" varchar(10) NOT NULL, "motivo_rechazo" varchar(250) NOT NULL, "fecha_revision" datetime NULL, "fecha_subida" datetime NOT NULL, "reproducciones" integer unsigned NOT NULL CHECK ("reproducciones" >= 0), "album_id" bigint NULL REFERENCES "musica_album" ("id") DEFERRABLE INITIALLY DEFERRED, "artista_id" bigint NOT NULL REFERENCES "usuarios_usuario" ("id") DEFERRABLE INITIALLY DEFERRED, "revisada_por_id" bigint NULL REFERENCES "usuarios_usuario" ("id") DEFERRABLE INITIALLY DEFERRED, "genero_id" bigint NULL REFERENCES "musica_genero" ("id") DEFERRABLE INITIALLY DEFERRED);
CREATE TABLE "musica_favorito" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "fecha_agregado" datetime NOT NULL, "cancion_id" bigint NOT NULL REFERENCES "musica_cancion" ("id") DEFERRABLE INITIALLY DEFERRED, "usuario_id" bigint NOT NULL REFERENCES "usuarios_usuario" ("id") DEFERRABLE INITIALLY DEFERRED);
CREATE TABLE "musica_genero" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "nombre" varchar(60) NOT NULL UNIQUE, "slug" varchar(70) NOT NULL UNIQUE, "descripcion" varchar(200) NOT NULL);
CREATE TABLE "musica_megusta" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "pista_id" varchar(64) NOT NULL, "titulo" varchar(200) NOT NULL, "artista" varchar(200) NOT NULL, "portada" varchar(500) NOT NULL, "preview" varchar(500) NOT NULL, "ficha" varchar(500) NOT NULL, "duracion" integer unsigned NOT NULL CHECK ("duracion" >= 0), "genero" varchar(60) NOT NULL, "fecha" datetime NOT NULL, "usuario_id" bigint NOT NULL REFERENCES "usuarios_usuario" ("id") DEFERRABLE INITIALLY DEFERRED, CONSTRAINT "me_gusta_unico" UNIQUE ("usuario_id", "pista_id"));
CREATE TABLE "musica_reproduccion" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "fecha" datetime NOT NULL, "cancion_id" bigint NOT NULL REFERENCES "musica_cancion" ("id") DEFERRABLE INITIALLY DEFERRED, "usuario_id" bigint NULL REFERENCES "usuarios_usuario" ("id") DEFERRABLE INITIALLY DEFERRED);
CREATE TABLE "socialaccount_socialaccount" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "provider" varchar(200) NOT NULL, "uid" varchar(191) NOT NULL, "last_login" datetime NOT NULL, "date_joined" datetime NOT NULL, "user_id" bigint NOT NULL REFERENCES "usuarios_usuario" ("id") DEFERRABLE INITIALLY DEFERRED, "extra_data" text NOT NULL CHECK ((JSON_VALID("extra_data") OR "extra_data" IS NULL)));
CREATE TABLE "socialaccount_socialapp" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "provider" varchar(30) NOT NULL, "name" varchar(40) NOT NULL, "client_id" varchar(191) NOT NULL, "secret" varchar(191) NOT NULL, "key" varchar(191) NOT NULL, "provider_id" varchar(200) NOT NULL, "settings" text NOT NULL CHECK ((JSON_VALID("settings") OR "settings" IS NULL)));
CREATE TABLE "socialaccount_socialtoken" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "token" text NOT NULL, "token_secret" text NOT NULL, "expires_at" datetime NULL, "account_id" integer NOT NULL REFERENCES "socialaccount_socialaccount" ("id") DEFERRABLE INITIALLY DEFERRED, "app_id" integer NULL REFERENCES "socialaccount_socialapp" ("id") DEFERRABLE INITIALLY DEFERRED);
CREATE TABLE "tienda_carrito" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "fecha_creacion" datetime NOT NULL, "actualizado" datetime NOT NULL, "usuario_id" bigint NOT NULL UNIQUE REFERENCES "usuarios_usuario" ("id") DEFERRABLE INITIALLY DEFERRED);
CREATE TABLE "tienda_carritoitem" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "nombre_album" varchar(200) NOT NULL, "formato" varchar(10) NOT NULL, "cantidad" integer unsigned NOT NULL CHECK ("cantidad" >= 0), "precio_unitario" decimal NOT NULL, "agregado" datetime NOT NULL, "album_id" bigint NOT NULL REFERENCES "musica_album" ("id") DEFERRABLE INITIALLY DEFERRED, "carrito_id" bigint NOT NULL REFERENCES "tienda_carrito" ("id") DEFERRABLE INITIALLY DEFERRED);
CREATE TABLE "tienda_pago" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "nombre_titular" varchar(120) NOT NULL, "ultimos_digitos" varchar(4) NOT NULL, "marca" varchar(20) NOT NULL, "vencimiento" varchar(5) NOT NULL, "monto_total" decimal NOT NULL, "estado" varchar(10) NOT NULL, "fecha_pago" datetime NOT NULL, "pedido_id" bigint NOT NULL UNIQUE REFERENCES "tienda_pedido" ("id") DEFERRABLE INITIALLY DEFERRED);
CREATE TABLE "tienda_pedido" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "numero" varchar(24) NOT NULL UNIQUE, "total" decimal NOT NULL, "estado" varchar(10) NOT NULL, "fecha" datetime NOT NULL, "usuario_id" bigint NOT NULL REFERENCES "usuarios_usuario" ("id") DEFERRABLE INITIALLY DEFERRED);
CREATE TABLE "tienda_pedidoitem" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "nombre_album" varchar(200) NOT NULL, "artista" varchar(150) NOT NULL, "formato" varchar(10) NOT NULL, "tipo_disco" varchar(10) NOT NULL, "cantidad" integer unsigned NOT NULL CHECK ("cantidad" >= 0), "precio_unitario" decimal NOT NULL, "album_id" bigint NULL REFERENCES "musica_album" ("id") DEFERRABLE INITIALLY DEFERRED, "pedido_id" bigint NOT NULL REFERENCES "tienda_pedido" ("id") DEFERRABLE INITIALLY DEFERRED);
CREATE TABLE "usuarios_usuario" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "password" varchar(128) NOT NULL, "last_login" datetime NULL, "is_superuser" bool NOT NULL, "username" varchar(150) NOT NULL UNIQUE, "first_name" varchar(150) NOT NULL, "last_name" varchar(150) NOT NULL, "is_staff" bool NOT NULL, "is_active" bool NOT NULL, "date_joined" datetime NOT NULL, "email" varchar(254) NOT NULL UNIQUE, "rol" varchar(10) NOT NULL, "avatar" varchar(100) NULL, "biografia" text NOT NULL, "fecha_registro" datetime NOT NULL, "bloqueado" bool NOT NULL, "motivo_bloqueo" varchar(200) NOT NULL);
CREATE TABLE "usuarios_usuario_groups" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "usuario_id" bigint NOT NULL REFERENCES "usuarios_usuario" ("id") DEFERRABLE INITIALLY DEFERRED, "group_id" integer NOT NULL REFERENCES "auth_group" ("id") DEFERRABLE INITIALLY DEFERRED);
CREATE TABLE "usuarios_usuario_user_permissions" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "usuario_id" bigint NOT NULL REFERENCES "usuarios_usuario" ("id") DEFERRABLE INITIALLY DEFERRED, "permission_id" integer NOT NULL REFERENCES "auth_permission" ("id") DEFERRABLE INITIALLY DEFERRED);
